/**
 * arch-style-lib :: icons
 * Name -> glyph lookup for the ArchSymbols icon font (css/icons.css,
 * fonts/SF-AlfredoSymbols.ttf). Reference icons by name in markup:
 *
 *   <span class="arch-icon" data-icon="square.and.arrow.down"></span>
 *
 * then call renderIcons() once on page load (and again after inserting new
 * icon markup dynamically) to fill in the actual glyph.
 *
 * Codepoints below were extracted directly from the Figma-exported PDF
 * catalogs in fonts/tools/ (name column) paired with each glyph's ToUnicode
 * CMap entry (decoded from the raw PDF content stream, not from PyMuPDF's
 * text layer, which mis-decodes supplementary-plane codepoints). Verified
 * against the source Figma document. See docs/icons.md.
 */

